function icon(name, extra='') { return `<svg class="icon ${extra}" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name] || icons.sport}"/></svg>`; }
function ib(name, label, action='back', extra='') { return `<button class="icon-button" aria-label="${e(label)}" data-act="${action}" ${extra}>${icon(name)}</button>`; }
function b(label, action, variant='', extra='') { return `<button class="button ${variant}" data-act="${action}" ${extra}>${label}</button>`; }
function nb(label, to, variant='', extra='') { return `<button class="button ${variant}" data-nav="${to}" ${extra}>${label}</button>`; }
function badge(text, type='') { return `<span class="badge ${type}">${e(text)}</span>`; }
function avatar(name, type='', size='') { const initials=name.split(/\s+/).slice(0,2).map(s=>s[0]).join(''); return `<span class="avatar ${type} ${size}">${e(initials)}</span>`; }
function meta(symbol, text) { return `<div class="meta">${icon(symbol)}<span>${e(text)}</span></div>`; }
function bar(title, right='', back=true) { return `<header class="appbar">${back?ib('back','Go back'):''}<h1>${e(title)}</h1>${right}</header>`; }
function footer(content) { return `<footer class="action-footer">${content}</footer>`; }
function nav(active) {
  return `<nav class="bottom-nav" aria-label="Primary">${[['home','home','Home'],['explore','explore','Explore'],['create-basics','plus','Create'],['activities','calendar','Activities'],['profile','user','Profile']].map(([id,i,t])=>`<button class="nav-item ${id===active?'active':''} ${i==='plus'?'create':''}" data-nav="${id}" aria-label="${t}" ${id===active?'aria-current="page"':''}>${i==='plus'?`<span class="create-nav">${icon(i)}</span>`:icon(i)}<span>${t}</span></button>`).join('')}</nav>`;
}
function field(label,name,value='',type='text',placeholder='',extra='') { return `<label class="field"><span>${e(label)}</span><input name="${name}" type="${type}" value="${e(value)}" placeholder="${e(placeholder)}" ${extra}></label>`; }
function password(label, name) { return `<label class="field"><span>${e(label)}</span><div class="password-wrap"><input name="${name}" type="password" autocomplete="${name==='password'&&current.id==='login'?'current-password':'new-password'}" required minlength="6" placeholder="At least 6 characters">${ib('eye','Show password','password',`data-field="${name}"`)}</div></label>`; }
function section(title,to='',label='View all') { return `<div class="section-head"><h2>${e(title)}</h2>${to?`<button class="link-button" data-nav="${to}">${e(label)}</button>`:''}</div>`; }
function layout(title,body,{bottom='',actions='',right='',back=true,cls=''}={}) { return `${bar(title,right,back)}<div class="content ${cls}">${body}</div>${actions?footer(actions):''}${bottom?nav(bottom):''}`; }
function empty(title,text,symbol='calendar',action='explore',label='Explore activities') { return `<div class="empty-state"><span class="empty-symbol">${icon(symbol)}</span><h2>${title}</h2><p>${text}</p>${action?nb(label,action):''}</div>`; }
