 const hub=mode==='empty'?`<div class="hub"><span class="hub-eyebrow">YOUR ACTIVITY HUB</span><h2>Your next plan starts here.</h2><p>A good game needs good company. Bring yours together.</p><div class="hub-actions">${nb('Create an activity','create-basics')}${nb('Discover plans '+icon('arrow'),'explore','ghost')}</div></div>`:mode==='pending'?`<div class="hub"><span class="hub-eyebrow">YOUR ACTIVITY HUB <span>2 TO REVIEW</span></span><h2>A full team is one tap closer.</h2><p>Two people want to join Friday five-a-side.</p><div class="hub-actions">${nb('Review requests','requests')}${nb('View activity','activity-host','ghost')}</div></div>`:mode==='hosting'?`<div class="hub"><span class="hub-eyebrow">YOUR ACTIVITY HUB <span>YOU’RE HOSTING</span></span><h2>Friday five-a-side</h2><p>Fri, 16 Oct · 8:00 PM · 8 of 10 players</p><div class="hub-actions">${nb('Manage activity','activity-host')}${nb('Group chat '+icon('chat'),'group-chat','ghost','data-activity="football"')}</div></div>`:`<div class="hub"><span class="hub-eyebrow">YOUR ACTIVITY HUB <span>UP NEXT</span></span><h2>After-work badminton</h2><p>Fri, 16 Oct · 7:00 PM</p><p>Shuttlers Arena, Bodakdev</p><div class="hub-actions">${nb('View activity','activity-joined')}${nb('Group chat '+icon('chat'),'group-chat','ghost','data-activity="badminton"')}</div></div>`;
 return `<header class="home-header"><div><div class="wordmark"><span class="brand-symbol">L<span></span></span>LastSpot</div><button class="city-button" data-act="choose-city">${icon('location')}${e(demo.city)} ${icon('down')}</button></div>${ib('bell','Notifications','navigate','data-to="notifications"')}<span class="sr-only">3 unread notifications</span></header><div class="content"><div class="greeting"><p>Hey ${e(demo.user.name.split(' ')[0])} 👋</p><h1>Make room for <span>more.</span></h1></div>${hub}${section('Find your people')}<div class="categories">${[['Cricket','🏏'],['Football','⚽'],['Badminton','🏸'],['Events','🌅']].map(([n,emoji])=>`<button class="category-button" data-act="category" data-value="${n}"><span class="category-visual">${emoji}</span>${n}</button>`).join('')}</div>${section('A few spots. A great plan.','explore')}${activityCard(activities.cricket)}${section('This weekend','explore')}${activityCard(activities.ride,{compact:true})}${activityCard(activities.event,{compact:true})}</div>${nav('home')}`;
