 const options=(key,label,values)=>`<div class="filter-section"><h3>${label}</h3><div class="filter-options">${values.map(v=>`<button class="chip ${f[key]===v?'selected':''}" data-act="filter" data-key="${key}" data-value="${v}">${v}</button>`).join('')}</div></div>`;
 return `${explore()}<div class="sheet-backdrop"><section class="sheet" aria-label="Filter activities"><div class="drag-handle"></div>${bar('Make it your kind of plan',ib('close','Close filters','cancel-filters'),false)}<div class="content">${options('category','Activity',['All','Cricket','Football','Badminton','Events','Ride sharing'])}${options('date','When',['Any date','This weekend'])}${options('spots','Spots available',['Any','1–2 spots'])}${options('price','Price',['Any price','Free','Paid'])}${options('status','Activity status',['Open & full','Open only'])}<p class="hint">Location: ${e(demo.city)}. Change city from Explore.</p></div>${footer(`<div class="button-row">${b('Reset','reset-filters','outline')}${b('Show activities','apply-filters')}</div>`)}</section></div>`;
