function authScreen(id) {
 const loading=current.state==='loading';
 const errors=current.state==='error'?'<div class="error-box">We couldn’t complete that request. Check your details and try again.</div>':'';
 const heads={login:['Welcome back.','Your next great plan is waiting.'],signup:['Find your people.','Create an account and make your next activity happen.'],'forgot-password':['Let’s get you back in.','Enter your email and we’ll send you a password reset link.'],'reset-password':['A fresh start.','Choose a new password for your LastSpot account.']};
 const fields=id==='login'?`${field('Email address','email','','email','you@example.com','required autocomplete="email"')}${password('Password','password')}<div style="text-align:right;margin-top:-10px;margin-bottom:20px"><button class="link-button" type="button" data-nav="forgot-password">Forgot password?</button></div>`:id==='signup'?`${field('Full name','name','','text','Your full name','required autocomplete="name"')}${field('Email address','email','','email','you@example.com','required autocomplete="email"')}${password('Password','password')}${password('Confirm password','confirm')}<label class="check-label"><input name="terms" type="checkbox" required><span>I agree to the <a href="#terms" data-nav="terms">Terms</a> and <a href="#privacy" data-nav="privacy">Privacy Policy</a>.</span></label>`:id==='forgot-password'?field('Email address','email','','email','you@example.com','required autocomplete="email"'):`${password('New password','password')}${password('Confirm new password','confirm')}`;
 const label={login:'Sign in',signup:'Create account','forgot-password':'Send reset link','reset-password':'Save new password'}[id];
 return layout('',`<div class="wordmark space-bottom"><span class="brand-symbol">L<span></span></span>LastSpot</div><div class="form-heading"><h1>${heads[id][0]}</h1><p>${heads[id][1]}</p></div>${errors}<form id="auth-form" data-form="${id}">${fields}<div id="form-error" role="alert"></div><button class="button" type="submit" ${loading?'disabled':''}>${loading?'<span class="spinner"></span> Working…':label}</button></form>${id==='login'?'<div class="form-bottom">New to LastSpot? <button data-nav="signup">Create an account</button></div>':id==='signup'?'<div class="form-bottom">Already have an account? <button data-nav="login">Sign in</button></div>':''}`);
}
function profileSetup(edit=false) {
 return layout(edit?'Edit profile':'Make it yours',`<div class="form-heading"><h1>${edit?'A little about you.':'Good plans start with you.'}</h1><p>${edit?'Let your activity community know who you are.':'Add a face, a name and a city. We’ll take it from there.'}</p></div><button class="photo-picker" data-act="photo" aria-label="Choose profile picture">${demo.user.photo?`<img src="${e(demo.user.photo)}" alt="Selected profile picture">`:icon('user')}<span>${icon('camera')}</span></button><input id="photo-input" type="file" accept="image/*" hidden><form id="profile-form" data-form="${edit?'edit-profile':'profile-setup'}">${field('Full name','name',demo.user.name,'text','','required autocomplete="name"')}<label class="field"><span>Your city</span><button type="button" class="button outline row between" data-act="choose-city">${icon('location')} ${e(demo.city)} ${icon('down')}</button></label><label class="field"><span>Bio <span class="muted">· optional</span></span><textarea name="bio" maxlength="180" placeholder="What brings you here?">${e(edit?demo.user.bio:'')}</textarea><small>Keep it friendly. Up to 180 characters.</small></label>${edit?`<label class="field"><span>Interests</span><button type="button" class="button outline" data-nav="interests">${e(demo.interests.join(' · '))} ${icon('edit')}</button></label>`:''}<div id="form-error" role="alert"></div></form>`,{actions:`<button type="submit" form="profile-form" class="button">${edit?'Save changes':'Continue'} ${icon('arrow')}</button>`});
}
function interests() { return layout('Your interests',`<div class="form-heading"><span class="overline">A LITTLE MORE YOU</span><h1 style="margin-top:10px">What gets you going?</h1><p>Pick the things you’d love to do with good company. You can change these later.</p></div><div class="interest-grid">${[['Cricket','🏏'],['Football','⚽'],['Badminton','🏸'],['Ride sharing','🚗'],['Events','🌅'],['Other activities','✨']].map(([name,emoji])=>`<button class="interest-tile ${demo.interests.includes(name)?'selected':''}" data-act="interest" data-value="${name}" aria-pressed="${demo.interests.includes(name)}"><i class="checkmark">${demo.interests.includes(name)?'✓':''}</i><span>${emoji}</span><strong>${name}</strong></button>`).join('')}</div>`,{actions:`<p class="hint center" style="margin-bottom:10px">${demo.interests.length} interests selected</p>${b('Save interests','save-interests','',demo.interests.length?'':'disabled')}`}); }
function cityScreen() { return layout('Choose your city',`<div class="form-heading"><h1>Where’s your next plan?</h1><p>Find activities and people in your city.</p></div><label class="search-input">${icon('search')}<input id="city-search" type="search" placeholder="Search cities" aria-label="Search cities"></label><div id="city-results">${cityRows('')}</div>`,{actions:b(`Confirm ${e(demo.draftCity)}`,'confirm-city')}); }
function cityRows(query) { const cities=['Ahmedabad','Vadodara','Surat','Rajkot','Gandhinagar'].filter(c=>c.toLowerCase().includes(query.toLowerCase()));return cities.length?cities.map(c=>`<button class="city-row" data-act="select-city" data-value="${c}"><span class="city-initial">${icon('location')}</span><span class="grow"><h3>${c}</h3><p>Gujarat, India</p></span><span class="radio ${demo.draftCity===c?'selected':''}"></span></button>`).join(''):empty('No city found','Try another spelling or choose one of the available cities.','search','',''); }
function detailScreen() {
 const a=selectedActivity(),role=current.id.replace('activity','').replace('-','')||'visitor';
 const status=role==='full'?'Activity full':role==='cancelled'?'Cancelled':role==='pending'?'Request pending':role==='joined'?'You’re going':role==='host'?'You’re hosting':'Open to join';
 const primary={visitor:b('Request to join','join'),pending:b('Request pending','noop','', 'disabled'),joined:nb('Open group chat '+icon('chat'),'group-chat','',`data-activity="${a.id}"`),host:nb('Review requests · 2','requests'),full:nb('Find another activity','explore'),cancelled:nb('Explore activities','explore')}[role];
 const capacity=role==='full'?a.max:a.joined;
 return `${bar('Activity details',ib('more','More activity actions','activity-menu'))}<div class="content flush"><div class="detail-hero">${court(a.art)}${badge(a.emoji+' '+a.category)}</div><div class="detail-copy"><div class="row between">${badge(status,role==='cancelled'?'error':role==='pending'?'warning':'success')}<span class="price">${a.price?'₹'+a.price:'Free'}${a.price?'<small> / person</small>':''}</span></div><h1>${e(a.title)}</h1>${role==='cancelled'?'<div class="error-box">This activity has been cancelled. Please check with the host if you have questions.</div>':''}<div class="detail-facts">${[['calendar',a.date,'2026'],['clock',a.time,'Arrive 10 min early'],['location',a.venue,a.area.split(',')[0]],['users',`${capacity} of ${a.max} people`,`${a.max-capacity} spots available`]].map(([i,t,s])=>`<div class="meta"><span class="icon-tile">${icon(i)}</span><span><strong>${e(t)}</strong><small>${e(s)}</small></span></div>`).join('')}</div><div class="host-block">${avatar(a.host,'coral')}<div class="grow"><h3>${e(a.host)}</h3><p>Activity host</p></div>${role==='pending'?nb('Message','direct-chat','small secondary',`data-activity="${a.id}"`):role==='host'?nb('Edit','create-basics','small secondary'):`<span class="hint">${e(demo.city)}</span>`}</div>${section('The plan')}<p class="description">${e(a.description)}</p>${section('People make the plan')}<div class="row between"><div class="avatar-stack">${avatar(a.host,'coral','tiny')}${avatar('Dev Joshi','mint','tiny')}${avatar('Kavya Patel','gold','tiny')}</div><span class="hint">${capacity} / ${a.max} joined</span></div><div class="capacity">${Array.from({length:a.max},(_,i)=>`<span class="${i<capacity?'filled':''}"></span>`).join('')}</div><p class="hint">${role==='visitor'||role==='pending'?'Participant details are available after you join.':'Coordinate with the group before you arrive.'}</p>${role==='host'?nb('Open group chat','group-chat','secondary space-top',`data-activity="${a.id}"`):''}${section('Meet here')}<button class="card row" style="width:100%;text-align:left;color:var(--ink)" data-act="venue"><span class="icon-tile">${icon('location')}</span><span class="grow"><strong style="font-size:12px">${e(a.venue)}</strong><span class="meta">${e(a.area)}</span></span>${icon('chevron')}</button><p class="hint" style="margin-top:8px">Venue directions open in your maps app.</p></div></div>${footer(primary)}`;
}
function createScreen() {
 const d=demo.creation,step={'create-basics':1,'create-details':2,'create-review':3}[current.id];
 const progress=`<div class="step-header">${[1,2,3].map(n=>`<span class="step-line ${n<=step?'done':''}"></span>`).join('')}</div><p class="step-label">STEP ${step} OF 3 · ${['','THE BASICS','THE DETAILS','READY TO GO'][step]}</p>`;
 let body;
 if(step===1) body=`<h1 class="page-heading">What’s the plan?</h1><p class="page-subtitle">A great activity starts with a simple idea.</p><form id="create-form" data-form="create-basics"><label class="field"><span>Activity category</span><select name="category">${['Cricket','Football','Badminton','Ride sharing','Events','Other activities'].map(n=>`<option ${d.category===n?'selected':''}>${n}</option>`).join('')}</select></label>${field('Activity title','title',d.title,'text','Give your plan a name','required maxlength="80"')}<label class="field"><span>Tell people about it</span><textarea name="description" required>${e(d.description)}</textarea><small>What should people expect or bring?</small></label><button class="photo-summary" type="button" data-act="activity-photo">${icon('image')}Add an activity photo <span class="muted">· optional</span></button><input id="activity-photo" type="file" accept="image/*" hidden><div id="form-error" role="alert"></div></form>`;
 else if(step===2) body=`<h1 class="page-heading">Make it happen.</h1><p class="page-subtitle">A place, a time and room for your people.</p><form id="create-form" data-form="create-details"><label class="field"><span>City</span><select name="city">${['Ahmedabad','Vadodara','Surat','Rajkot','Gandhinagar'].map(n=>`<option ${d.city===n?'selected':''}>${n}</option>`).join('')}</select></label>${field('Venue or meeting point','venue',d.venue,'text','Venue name or maps link','required')}<div class="inline-fields">${field('Date','date',d.date,'date','','required min="2026-10-14"')}${field('Time','time',d.time,'time','','required')}</div><div class="inline-fields">${field('Total participants','capacity',d.capacity,'number','','required min="2" max="1000"')}${field('Price per person · ₹','price',d.price,'number','','required min="0" step="1"')}</div><p class="hint">Set the price to 0 for a free activity. Payments are arranged with the host; no in-app payment is implied.</p><div id="form-error" role="alert"></div></form>`;
 else body=`<h1 class="page-heading">Looks like a good plan.</h1><p class="page-subtitle">Check the details. Your people will take it from here.</p><div class="activity-art" style="border-radius:16px">${d.photo?`<img src="${e(d.photo)}" alt="Your selected activity" style="width:100%;height:100%;object-fit:cover">`:court(d.category.toLowerCase())}</div><div class="review-section"><div class="row between">${badge(d.category)}<button class="link-button" data-nav="create-basics">Edit basics</button></div><h2 style="font-size:22px;margin:10px 0">${e(d.title)}</h2><p>${e(d.description)}</p></div><div class="divider"></div><div class="review-section"><div class="row between"><h3>The details</h3><button class="link-button" data-nav="create-details">Edit details</button></div>${meta('calendar',`${d.date} · ${d.time}`)}${meta('location',`${d.venue}, ${d.city}`)}${meta('users',`${d.capacity} total participants`)}<p style="margin-top:12px"><span class="price">${Number(d.price)?'₹'+e(d.price):'Free'}</span>${Number(d.price)?' per person':''}</p></div><div class="info-box">Your activity will be visible to people exploring ${e(d.city)}. Join requests will appear in Activities.</div>`;
 const actions=step<3?`<button class="button" type="submit" form="create-form">${step===1?'Continue':'Review activity'} ${icon('arrow')}</button>`:b(current.state==='loading'?'<span class="spinner"></span> Creating…':'Create activity','publish','',current.state==='loading'?'disabled':'');
 return layout('Create activity',progress+body,{actions,right:ib('close','Leave creation','leave-create')});
}
function activitiesScreen() {return layout('Activities',`<span class="overline">YOUR PLANS, TOGETHER</span><h1 class="page-heading">More than a calendar.</h1><p class="page-subtitle">The activities and people you’re showing up for.</p><div class="stats-row">${[['Hosting','2','hosting'],['Joined','3','joined'],['Pending',demo.accepted||demo.declined?'1':'2','requests']].map(([t,n,id])=>`<button class="stat" data-nav="${id}"><strong>${n}</strong><span>${t}</span></button>`).join('')}</div><button class="chat-entry" data-nav="chats"><span class="icon-tile">${icon('chat')}</span><span class="grow"><h3>Keep the conversation going</h3><p>Direct messages & activity groups</p></span><span class="unread-count">3</span>${icon('chevron')}</button>${section('You’re hosting','hosting')}${activityCard(activities.football,{compact:true,to:'activity-host'})}${section('You’re joining','joined')}${activityCard(activities.badminton,{compact:true,to:'activity-joined',status:'Accepted'})}${section('Requests')}<div class="card" style="padding:0 14px">${listLink('Received requests','People who want to join your plans','users','requests',demo.accepted||demo.declined?'1':'2')}${listLink('Sent requests','Keep track of your applications','send','sent-requests')}</div>`,{bottom:'activities',back:false,right:ib('bell','Notifications','navigate','data-to="notifications"')});}
function listLink(title,subtitle,symbol,to,count=''){return `<button class="list-row" data-nav="${to}"><span class="icon-tile">${icon(symbol)}</span><span class="grow"><h3>${title}</h3>${subtitle?`<p>${subtitle}</p>`:''}</span>${count?`<span class="badge">${count}</span>`:''}${icon('chevron','chevron')}</button>`;}
function activityList(hosting) {const a=hosting?activities.football:activities.badminton;return layout(hosting?'Hosting':'Joined activities',`<h1 class="page-heading">${hosting?'Your plans. Your people.':'See you there.'}</h1><p class="page-subtitle">${hosting?'Bring the last few people together.':'Your accepted activities, all in one place.'}</p>${section('Upcoming')}${activityCard(a,{to:hosting?'activity-host':'activity-joined',label:hosting?'Manage':'View activity'})}${nb('Open group chat '+icon('chat'),'group-chat','secondary',`data-activity="${a.id}"`)}${section('Past activities')}${activityCard({...activities.cricket,title:'Saturday box cricket',date:'Sat, 10 Oct'},{compact:true,to:'activity-cancelled',status:'Completed'})}`);}
function requestsScreen(sent=false) {
 const pending=!demo.accepted&&!demo.declined;
 return layout(sent?'Sent requests':'Received requests',`<h1 class="page-heading">${sent?'Your next plans.':'Room for one more?'}</h1><p class="page-subtitle">${sent?'Track your requests and keep in touch.':'Review people who want to join your activity.'}</p><div class="chip-row">${nb('Received','requests',`small ${sent?'outline':'secondary'}`)}${nb('Sent','sent-requests',`small ${sent?'secondary':'outline'}`)}</div>${sent?`<div class="card request-card space-top"><div class="row between">${badge('Pending','warning')}<span class="hint">Today</span></div><h3 style="font-size:16px;margin:12px 0">Sunday evening cricket</h3>${meta('calendar','Sun, 18 Oct · 7:00 PM')}${meta('location','Riverfront Sports Park')}<p class="request-note">Your request is with Nirav. We’ll let you know when there’s an update.</p><div class="button-row">${nb('View activity','activity-pending','small secondary')}${nb('Message host','direct-chat','small outline')}</div></div><div class="card request-card">${badge('Accepted','success')}<h3 style="margin:12px 0">After-work badminton</h3>${meta('calendar','Fri, 16 Oct · 7:00 PM')}${nb('Open group chat','group-chat','secondary space-top')}</div>`:`<div class="section-head"><h2>Friday five-a-side</h2>${badge(pending?'2 pending':'1 pending','warning')}</div>${pending?`<div class="card request-card"><div class="row">${avatar('Dev Joshi','mint')}<span class="grow"><h3>Dev Joshi</h3><span class="hint">Requested 20 minutes ago</span></span>${badge('Pending','warning')}</div><p class="request-note">“Hey! I’d love to join. I usually play midfield and can bring a ball.”</p>${nb('Review request','request-detail','secondary')}</div>`:`<div class="info-box space-bottom">Dev’s request was ${demo.accepted?'accepted. The group is now available to him.':'declined.'}</div>`}<div class="card request-card"><div class="row">${avatar('Kavya Joshi','coral')}<span><h3>Kavya Joshi</h3><span class="hint">Requested 45 minutes ago</span></span></div><p class="request-note">“Count me in if there’s still a spot!”</p>${nb('Review request','request-detail','secondary','data-applicant="Kavya Joshi"')}</div>`}`);
}
function requestDetail() {return layout('Review request',`<div class="profile-top">${avatar(demo.applicant||'Dev Joshi','mint','large')}<h1>${e(demo.applicant||'Dev Joshi')}</h1><p>Ahmedabad · Enjoys football and cricket</p></div><div class="card space-top"><span class="overline">WANTS TO JOIN</span><h2 style="font-size:18px;margin:9px 0">Friday five-a-side</h2>${meta('calendar','Fri, 16 Oct · 8:00 PM')}${meta('location','Playall Turf, Satellite')}<div class="divider"></div><p class="description">Hey! I’d love to join. I usually play midfield and can bring a ball.</p></div><div class="info-box space-top">${demo.accepted?'9':'8'} of 10 places filled. Accepting this request gives the participant access to the activity group.</div><p class="hint space-top">Decisions are confirmed by the server in the app. This prototype only demonstrates the interaction.</p>`,{actions:`<div class="button-row">${b('Decline','decline','outline')}${b('Accept request','accept')}</div>`});}
function chatsScreen(){const rows=[{name:'After-work badminton',sub:'Dev: मिलते हैं! The court code is B2.',time:'5:38 PM',count:2,type:'group',to:'group-chat',a:'badminton',context:'Activity group · 4 people'},{name:'Nirav Shah',sub:'Absolutely. All skill levels welcome!',time:'6:44 PM',count:1,type:'direct',to:'direct-chat',a:'cricket',context:'Sunday evening cricket'},{name:'Friday five-a-side',sub:'You: See everyone on Friday ⚽',time:'Yesterday',count:0,type:'group',to:'group-chat',a:'football',context:'Activity group · 8 people'}].filter(x=>demo.chatFilter==='all'||x.type===demo.chatFilter);return layout('Chats',`<h1 class="page-heading">Good plans start here.</h1><p class="page-subtitle">Stay close to the people you’re meeting.</p><div class="chip-row">${[['all','All'],['direct','Direct'],['group','Groups']].map(([v,t])=>`<button class="chip ${demo.chatFilter===v?'selected':''}" data-act="chat-filter" data-value="${v}">${t}</button>`).join('')}</div>${rows.map(x=>`<button class="chat-list-row" data-nav="${x.to}" data-activity="${x.a}">${x.type==='group'?`<span class="avatar">${activities[x.a].emoji}</span>`:avatar(x.name,'coral')}<span class="grow"><span class="row between"><h3>${x.name}</h3><time>${x.time}</time></span><p>${x.sub}</p><span class="row between"><span class="chat-context">${x.context}</span>${x.count?`<span class="unread-count">${x.count}</span>`:''}</span></span></button>`).join('')}`);}
function richText(text) {return text.split(/(`[^`\n]+`|\*[^*\n]+\*|_[^_\n]+_|~[^~\n]+~)/gu).map(p=>{const tag={'*':'strong','_':'em','~':'s','`':'code'}[p[0]];return tag&&p.length>2&&p.at(-1)===p[0]?`<${tag}>${e(p.slice(1,-1))}</${tag}>`:e(p);}).join('');}
function messageMarkup(m,i){return `<div class="message-row ${m.mine?'outgoing':''}"><div class="message" tabindex="0" data-message="${i}" aria-label="${e((m.mine?'You':m.sender)+': '+m.text)}">${!m.mine&&current.id==='group-chat'?`<span class="sender">${e(m.sender)}</span>`:''}${richText(m.text)}<time>${m.time}</time></div></div>`;}
function keyboardMarkup(){return `<div class="keyboard-preview" aria-label="Illustrative keyboard"><div>${[...'qwertyuiop'].map(x=>`<span>${x}</span>`).join('')}</div><div>${[...'asdfghjkl'].map(x=>`<span>${x}</span>`).join('')}</div><div>${[...'zxcvbnm'].map(x=>`<span>${x}</span>`).join('')}<span>⌫</span></div><div><span>123</span><span>☺</span><span class="space">space</span><span>↵</span></div></div>`;}
function chatScreen(group){const a=selectedActivity(),key=group?'group':'direct';const messages=current.state==='empty'?[]:demo.messages[key];return `<header class="appbar conversation-bar">${ib('back','Back to chats')}${group?`<span class="avatar">${a.emoji}</span>`:avatar(a.host,'coral')}<button class="conversation-title" data-nav="${group?'group-info':'activity-pending'}" data-activity="${a.id}"><h1>${e(group?a.title:a.host)}</h1><p>${group?`Activity group · ${a.joined} participants`:'Activity host'}</p></button>${ib(group?'info':'more',group?'Group information':'Conversation actions',group?'navigate':'chat-menu',group?`data-to="group-info" data-activity="${a.id}"`:'')}</header><button class="activity-context" data-nav="${group?'activity-joined':'activity-pending'}" data-activity="${a.id}">${icon('calendar')}<span class="grow">${e(a.title)} · ${a.date}</span>${icon('chevron')}</button><div class="content messages" id="message-list">${group?`<div class="chat-welcome"><span class="welcome-icon">${a.emoji}</span><h2>Welcome to ${e(a.title)}!</h2><p>This group is for coordinating the activity.<br>Be respectful and enjoy!</p></div>`:''}<span class="date-divider">Today, 14 October</span>${messages.length?messages.map(messageMarkup).join(''):empty('Say hello 👋','Start with a friendly message about the activity.','chat','','')}</div><form class="composer" id="composer"><textarea id="message-input" aria-label="Message" rows="1" placeholder="Message…" maxlength="4000"></textarea><button class="send-button" type="submit" aria-label="Send message">${icon('send')}</button></form>${keyboard?keyboardMarkup():''}`;}
function groupInfo(){const a=selectedActivity();return layout('Group information',`<div class="profile-top"><span class="avatar large" style="font-size:38px">${a.emoji}</span><h1>${e(a.title)}</h1><p>Activity group · ${a.joined} participants</p></div><div class="card space-top">${meta('calendar',`${a.date} · ${a.time}`)}${meta('location',`${a.venue}, ${a.area.split(',')[0]}`)}${nb('View activity','activity-joined','secondary space-top',`data-activity="${a.id}"`)}</div>${section('People in this plan')}${[a.host,'Aanya Patel','Dev Joshi'].map((name,i)=>`<div class="list-row">${avatar(name,i===0?'coral':i===2?'mint':'')}<div class="grow"><h3>${e(name)}${i===1?' (you)':''}</h3><p>${i===0?'Activity host':'Participant'}</p></div>${i===0?badge('Host'):''}</div>`).join('')}<p class="hint space-top">Only participants authorized for this activity are listed.</p>`);}
function notifications(){const items=[{id:1,icon:'users',title:'Dev wants to join your activity',body:'Friday five-a-side · Review their request.',time:'20 min ago',to:'request-detail',new:true},{id:2,icon:'chat',title:'Riya sent a message',body:'After-work badminton · “Court 2 is booked!”',time:'35 min ago',to:'group-chat',new:true},{id:3,icon:'check',title:'You’re in! See you on the court.',body:'Your badminton request was accepted.',time:'1 hour ago',to:'activity-joined',new:true},{id:4,icon:'calendar',title:'Your activity is coming up',body:'Friday five-a-side · Friday at 8:00 PM',time:'Yesterday',to:'activity-host',new:false},{id:5,icon:'info',title:'A request update',body:'Your request for the morning ride was declined.',time:'Yesterday',to:'sent-requests',new:false}].filter(x=>!demo.deletedNotifications.includes(x.id));return layout('Notifications',`<div class="row between"><h1 class="page-heading">You’re in the loop.</h1></div><div class="row between"><span class="hint">Updates that help your plans happen.</span><button class="link-button" data-act="read-all">Mark all read</button></div>${section('Today')}${items.map((n,i)=>`${n.time==='Yesterday'&&items[i-1]?.time!=='Yesterday'?section('Yesterday'):''}<article class="notification-row ${n.new&&!demo.notificationRead?'unread':''}"><span class="icon-tile ${n.icon==='check'?'green':''}">${icon(n.icon)}</span><button class="notification-target" data-nav="${n.to}" data-act-read="${n.id}"><h3>${n.title}</h3><p>${n.body}</p><time>${n.time}</time></button><button class="icon-button small" data-act="delete-notification" data-id="${n.id}" aria-label="Delete notification">${icon('trash')}</button></article>`).join('')}${items.length?'':empty('All caught up','New activity and conversation updates will appear here.','bell','','')}`);}
function profile(){return layout('Profile',`<div class="profile-top">${demo.user.photo?`<img class="avatar large" src="${e(demo.user.photo)}" alt="Your profile picture">`:avatar(demo.user.name,'','large')}<h1>${e(demo.user.name)}</h1><p>${e(demo.city)} · Here for good company</p><p>${e(demo.user.bio)}</p></div><div class="profile-interests">${demo.interests.map(n=>`<span class="chip">${e(n)}</span>`).join('')}</div>${nb('Edit profile '+icon('edit'),'edit-profile','outline')}<div class="stats-row">${[['2','Hosted'],['3','Joined'],['8','Completed']].map(([n,t])=>`<div class="stat"><strong>${n}</strong><span>${t}</span></div>`).join('')}</div><div class="card" style="padding:0 14px">${listLink('Notifications','Activity and message updates','bell','notifications')}${listLink('Settings','Make LastSpot feel like you','settings','settings')}${listLink('Help & support','','help','help')}${listLink('About LastSpot','','info','about')}</div><div class="card space-top" style="padding:0 14px">${listLink('Privacy information','','shield','privacy')}${listLink('Terms & conditions','','info','terms')}</div>${nb('Log out','logout','ghost space-top')}`,{bottom:'profile',back:false});}
function settings(){return layout('Settings',`<h1 class="page-heading">Make yourself at home.</h1><p class="page-subtitle">A few ways to make LastSpot yours.</p>${section('Appearance')}<div class="settings-choice">${['light','dark','system'].map(t=>`<button class="appearance-option ${theme===t?'selected':''}" data-act="appearance" data-value="${t}"><span class="appearance-mini ${t}"><i></i><i></i><i></i></span>${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div>${section('App color')}<div class="color-options">${[['#5948e8','Violet'],['#4334c8','Deep violet'],['#752a21','Terracotta']].map(([c,n],i)=>`<button class="color-option ${(!demo.accent&&i===0)||demo.accent===c?'selected':''}" style="background:${c}" data-act="accent" data-value="${c}" aria-label="${n}">${(!demo.accent&&i===0)||demo.accent===c?icon('check'):''}</button>`).join('')}</div>${section('Language')}<div class="card"><div class="row between"><div><strong style="font-size:13px">English</strong><p class="hint" style="margin-top:5px">App language</p></div><span class="radio selected"></span></div></div><p class="hint space-top">Messages and names support Gujarati, Hindi, English and emoji. Additional app translations need reviewed language files.</p>${section('Your information')}<div class="card" style="padding:0 14px">${listLink('Privacy information','','shield','privacy')}${listLink('Help & support','','help','help')}</div>`);}
function support(){return layout('Help & support',`<div class="empty-state" style="padding-top:30px"><span class="empty-symbol">${icon('help')}</span><h2>We’re here to help.</h2><p>Need a hand with your account, an activity, or a conversation?</p></div><div class="card"><span class="overline">CONTACT LASTSPOT</span><h2 style="font-size:19px;margin:10px 0">Let’s figure it out together.</h2><p class="description">Send the support team a note with a short description of what happened.</p>${b(icon('mail')+' Contact support','support','secondary space-top')}<p class="hint center" style="margin-top:10px">support@lastspot.com</p></div><div class="card space-top" style="padding:0 14px">${listLink('Privacy information','','shield','privacy')}${listLink('Report a concern','','flag','report')}</div>`);}
function legal(terms){return layout(terms?'Terms & conditions':'Privacy information',`<span class="overline">LASTSPOT / ${terms?'TERMS':'YOUR PRIVACY'}</span><h1 class="page-heading">${terms?'A community that works.':'Your information matters.'}</h1><p class="page-subtitle">Readable information, whenever you need it.</p><div class="info-box">Design preview: these headings show the reading layout. The Flutter implementation must retain the existing approved legal content.</div><div class="legal">${(terms?['Using LastSpot','Creating and joining activities','Respecting other participants','Account access and safety','Contact and support']:['Information you provide','Activity and message information','How information is used','Your choices and account','Contact and support']).map((x,i)=>`<h2>${i+1}. ${x}</h2><p>${terms?'This section presents the existing LastSpot terms in a clear, scrollable format. Headings and comfortable line spacing help people find the information relevant to their activities.':'This section presents the existing privacy information without hiding it behind complex navigation. Keep the approved policy wording, dates and contact details when implementing this layout.'}</p>`).join('')}</div>`);}
function report(){return layout('Report a concern',`<div class="form-heading"><h1>Help keep it welcoming.</h1><p>Tell us what happened. Reports are handled by the moderation process.</p></div><form id="report-form" data-form="report"><label class="field"><span>Reason</span><select name="reason" required><option value="">Choose a reason</option><option>Inappropriate behavior</option><option>Misleading activity</option><option>Spam</option><option>Other</option></select></label><label class="field"><span>Additional details · optional</span><textarea name="details" placeholder="Anything else that would help us understand?" maxlength="1000"></textarea></label><div id="form-error" role="alert"></div></form><div class="info-box">Please avoid sharing passwords, private contact details or payment information.</div>`,{actions:'<button type="submit" form="report-form" class="button">Send report</button>'});}
function systemScreen(id){const map={'session-expired':['Let’s get you signed in.','Your session has ended. Sign in again to return to your activities and conversations.','shield','login','Sign in again'],maintenance:['A little time out.','LastSpot is temporarily unavailable. Please try again shortly.','settings','splash','Try again'],'force-update':['A better LastSpot awaits.','Update the app to keep discovering activities and coordinating your plans.','refresh','','Update LastSpot']};const [title,desc,symbol,to,label]=map[id];return `${bar('', '',false)}<div class="system-state">${empty(title,desc,symbol,to,label)}${id==='force-update'?`<div style="position:absolute;bottom:160px;left:40px;right:40px">${b(label,'store')}</div>`:''}</div>`;}
function permission(){return layout('',`<div class="intro-art" style="height:200px">${court('badminton',true)}</div><div class="form-heading"><h1>Stay in the loop.</h1><p>Know when someone accepts your request, messages the group, or updates your activity.</p></div>${current.state==='denied'?'<div class="error-box">Notifications are off. You can still find every update in the Notifications screen.</div>':''}<div class="row space-bottom"><span class="icon-tile">${icon('bell')}</span><p class="description">Useful updates for the plans you care about.</p></div>`,{actions:`${b('Continue','permission')}${nb('Not now','home','ghost')}`});}
function renderScreen(){switch(current.id){
 case 'splash':return `<div class="splash-content"><span class="brand-symbol">L<span></span></span><h1>LastSpot</h1><p>Good plans. Great company.</p><span class="spinner" aria-label="Loading"></span></div><div class="splash-bottom">FIND PEOPLE. MAKE IT HAPPEN.</div>`;
 case 'welcome':return `<div class="content welcome-content"><div class="wordmark" style="margin-top:14px"><span class="brand-symbol">L<span></span></span>LastSpot</div><div class="intro-art">${court('badminton',true)}</div><span class="overline">YOUR PEOPLE ARE OUT THERE</span><h1>One last spot.<br><span>A whole new plan.</span></h1><p>Find people for the things you love.<br>From a friendly match to your next local adventure.</p>${nb('Find your people '+icon('arrow'),'signup')}<div class="form-bottom">Already part of the crew? <button data-nav="login">Sign in</button></div></div>`;
 case 'login':case 'signup':case 'forgot-password':case 'reset-password':return authScreen(current.id);
 case 'recovery-sent':return layout('',`${empty('Check your inbox.','We’ve sent a reset link to the email you entered. Follow it to choose your new password.','mail','login','Back to sign in')}<p class="hint center">For this prototype:</p>${nb('Preview the verified reset link','reset-password','ghost')}`);
 case 'profile-setup':return profileSetup();case 'edit-profile':return profileSetup(true);case 'interests':return interests();case 'city':return cityScreen();case 'home':return home();case 'explore':return explore();case 'filters':return filterScreen();
 case 'activity':case 'activity-pending':case 'activity-joined':case 'activity-host':case 'activity-full':case 'activity-cancelled':return detailScreen();
 case 'create-basics':case 'create-details':case 'create-review':return createScreen();
 case 'create-success':return layout('',`<div class="success-medallion">${icon('check')}</div><div class="center"><span class="overline">LET THE GOOD PLANS BEGIN</span><h1 class="page-heading" style="margin-top:12px">Your activity is live.</h1><p class="page-subtitle">There’s room for a few more.<br>We’ll keep you posted when requests arrive.</p></div><div class="card"><span class="badge">${e(demo.creation.category)}</span><h2 style="font-size:20px;margin:12px 0">${e(demo.creation.title)}</h2>${meta('calendar',`${demo.creation.date} · ${demo.creation.time}`)}${meta('location',demo.creation.venue)}</div>${nb('View activity','activity-host','space-top','data-created="true"')}${nb('Manage activities','activities','secondary space-top')}`);
 case 'activities':return activitiesScreen();case 'hosting':return activityList(true);case 'joined':return activityList(false);case 'requests':return requestsScreen();case 'sent-requests':return requestsScreen(true);case 'request-detail':return requestDetail();case 'chats':return chatsScreen();case 'direct-chat':return chatScreen(false);case 'group-chat':return chatScreen(true);case 'group-info':return groupInfo();case 'notifications':return notifications();case 'profile':return profile();case 'settings':return settings();case 'help':return support();case 'privacy':return legal(false);case 'terms':return legal(true);case 'report':return report();
 case 'about':return layout('About LastSpot',`<div class="profile-top" style="padding:30px 0"><span class="brand-symbol" style="width:68px;height:68px;font-size:48px;border-radius:20px">L<span></span></span><h1 style="margin-top:20px">LastSpot</h1><p>Find people. Fill the last spot.<br>Make the activity happen.</p><span class="badge neutral" style="margin-top:16px">Version 1.0.3</span></div><p class="description">A little more company can make a plan happen. LastSpot brings people together through sports, shared rides and local activities.</p><div class="card space-top" style="padding:0 14px">${listLink('Help & support','','help','help')}${listLink('Privacy information','','shield','privacy')}${listLink('Terms & conditions','','info','terms')}</div>`);
 case 'logout':return `${profile()}<div class="dialog-backdrop"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="logout-title"><span class="icon-tile">${icon('logout')}</span><h2 id="logout-title">Heading out?</h2><p>You’ll be signed out of LastSpot on this device. Your activities and conversations will be here when you return.</p><div class="button-row">${nb('Stay','profile','outline')}${b('Log out','logout','danger')}</div></section></div>`;
 case 'session-expired':case 'maintenance':case 'force-update':return systemScreen(current.id);case 'permission':return permission();default:return home();
}}

function stateScreen(screen) {
 const primary=['home','explore','activities','profile'].includes(screen.id)?screen.id:'';
 if(current.state==='loading'&&!['login','signup','forgot-password','reset-password','create-review'].includes(screen.id)) return layout(screen.name,`<div aria-label="Loading ${e(screen.name)}" role="status"><div class="skeleton short" style="height:27px;margin-top:15px"></div><div class="skeleton tiny"></div>${[1,2,3].map(()=>'<div class="skeleton-row"><span class="skeleton-avatar"></span><div class="grow"><div class="skeleton short"></div><div class="skeleton"></div></div><div class="skeleton card-block"></div>').join('')}</div>`,{bottom:primary,back:!primary});
 if(current.state==='error'&&!['login','signup','forgot-password','reset-password','create-basics','create-details','create-review','profile-setup','edit-profile','report'].includes(screen.id)) return layout(screen.name,empty('A little connection trouble.','We couldn’t load this just now. Check your connection and try again.','wifi',screen.id,'Try again'),{bottom:primary,back:!primary});
 if(current.state==='empty'&&!['home','direct-chat','group-chat'].includes(screen.id)) {
   const states={explore:['No plans found.','Try a different category or city. Your next activity could be one filter away.','search','explore','Clear filters'],city:['No city found.','Try another spelling. We currently support five cities in Gujarat.','search','city','Search again'],activities:['Your next plan starts here.','Create an activity or find one that’s right for you.','calendar','explore','Discover activities'],hosting:['Bring your people together.','Create your first activity and let others fill the last few spots.','users','create-basics','Create an activity'],joined:['Find something you’ll love.','Your accepted activities will appear here.','calendar','explore','Explore activities'],requests:['No requests to review.','We’ll let you know when someone wants to join your activity.','users','hosting','View hosting activities'],'sent-requests':['No requests sent yet.','Find an activity that interests you and ask to join.','send','explore','Find an activity'],chats:['Good conversations start with a plan.','Your direct messages and activity groups will appear here.','chat','activities','View activities'],notifications:['You’re all caught up.','New activity and message updates will appear here.','bell','home','Back to Home']};
   return layout(screen.name,empty(...(states[screen.id]||states.activities)),{bottom:primary,back:!primary});
 }
 let markup=renderScreen();
 if(current.state==='error'&&!['login','signup','forgot-password','reset-password'].includes(screen.id)) markup=markup.replace(/(<div class="content[^>]*>)/,'$1<div class="error-box" role="alert">We couldn’t save those changes. Your details are still here. Please try again.</div>');
 return markup;
}
function readRoute(){const [id,query='']=location.hash.slice(1).split('?');const p=new URLSearchParams(query);const screen=SCREENS.find(s=>s.id===id)||SCREENS.find(s=>s.id==='home');return {id:screen.id,state:screen.states.includes(p.get('state'))?p.get('state'):'default',activity:p.get('a')};}
function go(id,{state='default',activity=null,replace=false}={}) {
 if(!SCREENS.some(s=>s.id===id)) return;
 if(id==='city'){demo.cityReturn=current.id;demo.draftCity=demo.city;}
 if(id==='filters') demo.draftFilters={...demo.filters};
 if(id==='interests') demo.interestReturn=current.id==='edit-profile'?'edit-profile':'home';
 const params=new URLSearchParams();if(state!=='default')params.set('state',state);if(activity)params.set('a',activity);
 const next=id+(params.size?'?'+params.toString():'');
 if(location.hash.slice(1)===next){render();return;}
 if(!replace)stack.push(location.hash.slice(1)||'home');
 location.hash=next;
}
function back(){const fallback={'direct-chat':'chats','group-chat':'chats','group-info':'group-chat',hosting:'activities',joined:'activities',requests:'activities','sent-requests':'activities',chats:'activities',city:demo.cityReturn,filters:'explore','create-details':'create-basics','create-review':'create-details',logout:'profile',login:'welcome',signup:'welcome'}[current.id]||'home';const last=stack.pop();if(last&&last!==location.hash.slice(1)){location.hash=last;}else go(fallback,{replace:true});}
function clearFeedback(){clearTimeout(feedbackTimer);$('#feedback').innerHTML='';}
function toast(message,{persistent=false}={}){clearFeedback();$('#feedback').innerHTML=`<div class="toast" role="status"><span>${e(message)}</span><button data-act="dismiss-feedback">Dismiss</button></div>`;if(!persistent)feedbackTimer=setTimeout(clearFeedback,3000);}
function banner({name='Nirav Shah',activity='Sunday evening cricket',to='direct-chat',id='cricket'}={}){clearFeedback();$('#feedback').innerHTML=`<div class="notification-banner" role="status"><span class="icon-tile">${icon('chat')}</span><button class="banner-body" data-nav="${to}" data-activity="${id}"><strong>${e(name)}</strong><span>${e(activity)}</span><span>New message · Tap to open</span></button>${ib('close','Dismiss notification','dismiss-feedback')}</div>`;feedbackTimer=setTimeout(clearFeedback,5000);}
let modalReturnFocus;
function modal(title,text,actions,symbol='info'){modalReturnFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="dialog-backdrop" data-modal-backdrop><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="modal-title"><span class="icon-tile">${icon(symbol)}</span><h2 id="modal-title">${e(title)}</h2><p>${e(text)}</p>${actions}</section></div>`;$('#modal-root button, #modal-root a')?.focus();}
function closeModal(){$('#modal-root').innerHTML='';modalReturnFocus?.focus?.();}
function formError(text){const box=$('#form-error');if(box){box.innerHTML=`<div class="error-box" role="alert">${e(text)}</div>`;box.scrollIntoView({block:'nearest'});}else toast(text,{persistent:true});}
function saveDraft(){const form=$('#create-form');if(form)for(const [k,v]of new FormData(form))demo.creation[k]=v;}
function buildIndex(query=''){let number=0;$('#screen-index').innerHTML=SCREEN_GROUPS.map(([group,items])=>{const links=items.map(([id,name])=>{number++;return {id,name,number};}).filter(x=>`${x.name} ${group}`.toLowerCase().includes(query.toLowerCase()));return links.length?`<section class="nav-group"><h2>${group}</h2>${links.map(x=>`<a class="screen-link ${current.id===x.id?'active':''}" href="#${x.id}" data-nav="${x.id}" data-catalog="true"><span>${String(x.number).padStart(2,'0')}</span>${x.name}</a>`).join('')}</section>`:'';}).join('');}
function render(){
 clearTimeout(routeTimer);clearFeedback();closeModal();renderVersion++;
 current=readRoute();const screen=SCREENS.find(s=>s.id===current.id);
 $('#phone').dataset.theme=theme==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):theme;
 $('#phone').dataset.platform=platform;
 $('#phone').style.removeProperty('--brand');if(demo.accent&&theme==='light')$('#phone').style.setProperty('--brand',demo.accent);
 $('#app').innerHTML=stateScreen(screen);
 $('#screen-title').textContent=screen.name;$('#spec-title').textContent=screen.name;$('#spec-purpose').textContent=screen.purpose;$('#spec-action').textContent=screen.action;$('#spec-navigation').textContent=screen.navigation;$('#spec-route').textContent=screen.route;$('#screen-number').textContent=`${String(SCREENS.indexOf(screen)+1).padStart(2,'0')} / ${SCREENS.length}`;
 $('#state-picker').innerHTML=['default',...screen.states].map(s=>`<option value="${s}" ${s===current.state?'selected':''}>${s[0].toUpperCase()+s.slice(1)}</option>`).join('');
 $('#theme-picker').value=theme==='system'?'light':theme;$('#platform-picker').value=platform;
 buildIndex($('#screen-search').value);
 if(current.id==='splash'&&!exportMode)routeTimer=setTimeout(()=>go('welcome',{replace:true}),1600);
 document.title=`${screen.name} · LastSpot design prototype`;
}
const journeys=[['Discover → request to join','explore'],['Create → host an activity','create-basics'],['Review → accept a participant','requests'],['Direct conversation','direct-chat'],['Activity group → information','group-chat'],['Update → destination','notifications'],['Welcome → profile setup','welcome'],['Manage hosting & joined plans','activities'],['Preview verified recovery link','reset-password']];
$('#journeys').innerHTML=journeys.map(([label,id])=>`<button data-nav="${id}">${label} ${icon('arrow')}</button>`).join('');
document.addEventListener('click',event=>{
 const control=event.target.closest('[data-nav],[data-act],[data-scenario]');if(!control||control.disabled)return;
 event.preventDefault();
 if(control.dataset.nav){
   saveDraft();let id=control.dataset.nav;
   if(control.dataset.applicant)demo.applicant=control.dataset.applicant;
   if(id==='explore'&&current.state==='empty'){demo.search='';demo.filters=initialDemo().filters;}
   if(id==='create-basics'&&current.id==='activity-host'){const a=selectedActivity();demo.creation={...demo.creation,title:a.title,category:a.category,description:a.description,venue:a.venue,capacity:String(a.max),price:String(a.price)};}
   if(control.dataset.created){const d=demo.creation;activities.created={id:'created',category:d.category,emoji:'✨',title:d.title,date:d.date,time:d.time,venue:d.venue,area:d.city,host:demo.user.name,price:Number(d.price),joined:1,max:Number(d.capacity),art:d.category.toLowerCase(),description:d.description};}
   go(id,{activity:control.dataset.created?'created':control.dataset.activity||null});return;
 }
 if(control.dataset.scenario){scenario(control.dataset.scenario);return;}
 const value=control.dataset.value;
 switch(control.dataset.act){
  case 'back':saveDraft();back();break;
  case 'navigate':go(control.dataset.to,{activity:control.dataset.activity});break;
  case 'password':{const input=$(`[name="${control.dataset.field}"]`);input.type=input.type==='password'?'text':'password';control.setAttribute('aria-label',input.type==='password'?'Show password':'Hide password');break;}
  case 'choose-city':go('city');break;
  case 'select-city':demo.draftCity=value;$('#city-results').innerHTML=cityRows($('#city-search').value);$('.action-footer .button').textContent='Confirm '+value;break;
  case 'confirm-city':demo.city=demo.draftCity;go(demo.cityReturn,{replace:true});break;
  case 'interest':demo.interests=demo.interests.includes(value)?demo.interests.filter(x=>x!==value):[...demo.interests,value];render();break;
  case 'save-interests':go(demo.interestReturn||'home');break;
  case 'photo':$('#photo-input').click();break;
  case 'activity-photo':$('#activity-photo').click();break;
  case 'category':demo.filters.category=value;if(current.id==='explore'){render();}else go('explore');break;
  case 'filter':demo.draftFilters[control.dataset.key]=value;render();break;
  case 'reset-filters':demo.draftFilters={...initialDemo().filters};render();break;
  case 'apply-filters':demo.filters={...demo.draftFilters};go('explore');break;
  case 'cancel-filters':demo.draftFilters=null;go('explore');break;
  case 'join':demo.requestStatus='pending';go('activity-pending',{activity:selectedActivity().id});break;
  case 'accept':demo.accepted=true;demo.declined=false;activities.football.joined=9;go('requests');break;
  case 'decline':modal('Decline this request?','The applicant will see that the request was declined. They will not gain access to the activity group.',`<div class="button-row">${b('Keep pending','close-modal','outline')}${b('Decline','confirm-decline','danger')}</div>`,'users');break;
  case 'confirm-decline':demo.declined=true;demo.accepted=false;go('requests');break;
  case 'chat-filter':demo.chatFilter=value;render();break;
  case 'dismiss-feedback':clearFeedback();break;
  case 'close-modal':closeModal();break;
  case 'read-all':demo.notificationRead=true;render();toast('All notifications marked as read.');break;
  case 'delete-notification':demo.deletedNotifications.push(Number(control.dataset.id));render();toast('Notification removed.');break;
  case 'appearance':theme=value;render();break;
  case 'accent':demo.accent=value;render();break;
  case 'logout':clearFeedback();demo=initialDemo();stack=[];go('login',{replace:true});break;
  case 'leave-create':saveDraft();modal('Keep this plan for later?','Your draft stays available while you explore this prototype. You can also discard it and start fresh.',`<div class="button-row">${b('Keep editing','close-modal','outline')}${b('Leave draft','leave-draft','secondary')}</div>${b('Discard draft','discard-draft','ghost space-top')}`,'edit');break;
  case 'leave-draft':go('home');break;
  case 'discard-draft':demo.creation=initialDemo().creation;go('home');break;
  case 'publish':{const version=renderVersion;control.disabled=true;control.innerHTML='<span class="spinner"></span> Creating…';routeTimer=setTimeout(()=>{if(version===renderVersion)go('create-success');},550);break;}
  case 'activity-menu':modal('Activity options','View the activity context or report a concern.',`${nb('Report this activity','report','secondary')}${b('Close','close-modal','ghost space-top')}`,'flag');break;
  case 'chat-menu':modal('Conversation options','Open the related activity or report a concern.',`${nb('View activity','activity-pending','secondary',`data-activity="${selectedActivity().id}"`)}${nb('Report a concern','report','outline space-top')}${b('Close','close-modal','ghost space-top')}`,'chat');break;
  case 'venue':modal(selectedActivity().venue,selectedActivity().area,`<a class="button" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(selectedActivity().venue+' '+selectedActivity().area)}">Open Maps ${icon('arrow')}</a>${b('Stay here','close-modal','ghost space-top')}`,'location');break;
  case 'support':modal('Contact LastSpot','Share a short description of your question with support@lastspot.com.',`<a class="button" href="mailto:support@lastspot.com?subject=LastSpot%20support">Open email app ${icon('mail')}</a>${b('Close','close-modal','ghost space-top')}`,'mail');break;
  case 'store':modal('Open your app store','The production app opens its configured store listing. This design prototype has no store destination.',b('Back to preview','close-modal'),'refresh');break;
  case 'permission':modal('Allow activity updates?','This demonstrates the decision before the system permission prompt. The prototype does not request browser notifications.',`<div class="button-row">${b('Not now','deny-permission','outline')}${b('Allow','allow-permission')}</div>`,'bell');break;
  case 'deny-permission':closeModal();go('permission',{state:'denied'});break;
  case 'allow-permission':go('home');break;
  case 'copy-message':copyMessage();break;
 }
});
document.addEventListener('submit',event=>{
 const form=event.target;event.preventDefault();
 if(form.id==='composer'){const input=$('#message-input');const text=input.value.trim();if(!text)return;const key=current.id==='group-chat'?'group':'direct';demo.messages[key].push({mine:true,text,time:'Now'});if(current.state==='empty'){current.state='default';history.replaceState(null,'','#'+current.id+(current.activity?'?a='+current.activity:''));}const messages=$('#message-list');const placeholder=$('.empty-state',messages);if(placeholder)placeholder.remove();messages.insertAdjacentHTML('beforeend',messageMarkup(demo.messages[key].at(-1),demo.messages[key].length-1));input.value='';input.style.height='43px';messages.scrollTop=messages.scrollHeight;input.focus();return;}
 const data=Object.fromEntries(new FormData(form));const kind=form.dataset.form;
 if(!form.reportValidity())return;
 if(data.confirm!==undefined&&data.password!==data.confirm){formError('Your passwords don’t match yet. Please try again.');return;}
 if(kind==='login'){go('home');return;}if(kind==='signup'){demo.user.name=data.name;go('profile-setup');return;}if(kind==='forgot-password'){demo.recoveryEmail=data.email;go('recovery-sent');return;}if(kind==='reset-password'){go('login');return;}
 if(kind==='profile-setup'||kind==='edit-profile'){demo.user.name=data.name;demo.user.bio=data.bio;go(kind==='profile-setup'?'interests':'profile');return;}
 if(kind==='create-basics'||kind==='create-details'){Object.assign(demo.creation,data);go(kind==='create-basics'?'create-details':'create-review');return;}
 if(kind==='report'){modal('Thanks for letting us know.','Your report has been submitted in this prototype. The app uses the existing moderation process.',nb('Back to Activities','activities'),'check');}
});
document.addEventListener('input',event=>{
 const input=event.target;
 if(input.id==='city-search')$('#city-results').innerHTML=cityRows(input.value);
 if(input.id==='activity-search'){demo.search=input.value;const list=filteredActivities();$('#result-count').textContent=`${list.length} activities in ${demo.city}`;$('#explore-results').innerHTML=list.length?list.map(a=>activityCard(a)).join(''):empty('No matching activities','Try another category, city or a broader search.','search','explore','Reset your search');}
 if(input.id==='message-input'){input.style.height='43px';input.style.height=Math.min(input.scrollHeight,100)+'px';}
 if(input.id==='screen-search')buildIndex(input.value);
});
document.addEventListener('change',event=>{
 const input=event.target;
 if(input.id==='theme-picker'){theme=input.value;render();}if(input.id==='platform-picker'){platform=input.value;render();}if(input.id==='state-picker'){go(current.id,{state:input.value,activity:current.activity});}
 if(input.id==='photo-input'||input.id==='activity-photo'){const file=input.files[0];if(!file)return;if(!file.type.startsWith('image/')){toast('Choose an image file.');return;}if(file.size>8*1024*1024){toast('Choose a photo smaller than 8 MB.');return;}const reader=new FileReader();const version=renderVersion;reader.onload=()=>{if(version!==renderVersion)return;if(input.id==='photo-input'){demo.user.photo=reader.result;render();}else{saveDraft();demo.creation.photo=reader.result;$('.photo-summary').innerHTML=icon('check')+' Photo added';}};reader.readAsDataURL(file);}
});
function scenario(kind){
 if(kind==='keyboard'){keyboard=!keyboard;if(!['direct-chat','group-chat'].includes(current.id))go('direct-chat');else render();return;}
 if(kind==='expired'){clearFeedback();stack=[];go('session-expired',{replace:true});return;}
 if(kind==='current'){
   if(!['direct-chat','group-chat'].includes(current.id)){go('group-chat');return;}
   const key=current.id==='group-chat'?'group':'direct';const m={sender:current.id==='group-chat'?'Riya':'Nirav',text:'See you soon! 👋',time:'Now'};demo.messages[key].push(m);$('#message-list').insertAdjacentHTML('beforeend',messageMarkup(m,demo.messages[key].length-1));$('#message-list').scrollTop=$('#message-list').scrollHeight;return;
 }
 if(['login','welcome','signup','session-expired'].includes(current.id)){toast('Sign in to view activity notifications.');return;}
 if(kind==='rapid'){banner({name:'Dev Joshi',activity:'Friday five-a-side',to:'group-chat',id:'football'});banner({name:'Kavya Joshi',activity:'Sunset by the river',to:'group-chat',id:'event'});banner({name:'Nirav Shah',activity:'Sunday evening cricket'});return;}
 const isDirect=current.id==='direct-chat';banner(isDirect?{name:'Riya Mehta',activity:'After-work badminton',to:'group-chat',id:'badminton'}:{});
}
function openCopy(index){const key=current.id==='group-chat'?'group':'direct';copyText=demo.messages[key][index]?.text||'';if(!copyText)return;modal('Message options','Copy the original message, including its formatting marks.',`${b(icon('copy')+' Copy message','copy-message','secondary')}${b('Cancel','close-modal','ghost space-top')}`,'chat');}
async function copyMessage(){try{await navigator.clipboard.writeText(copyText);closeModal();toast('Message copied.');}catch{modal('Copy message','Select and copy the original text below.',`<textarea class="copy-fallback" aria-label="Original message" readonly style="width:100%;min-height:100px">${e(copyText)}</textarea>${b('Done','close-modal','space-top')}`,'copy');$('.copy-fallback').select();}}
let pressTimer;
document.addEventListener('contextmenu',event=>{const m=event.target.closest('[data-message]');if(m){event.preventDefault();openCopy(Number(m.dataset.message));}});
document.addEventListener('pointerdown',event=>{const m=event.target.closest('[data-message]');if(m)pressTimer=setTimeout(()=>openCopy(Number(m.dataset.message)),600);});
for(const name of ['pointerup','pointercancel','pointermove'])document.addEventListener(name,()=>clearTimeout(pressTimer));
document.addEventListener('keydown',event=>{
 if(event.target.id==='message-input'&&event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();$('#composer').requestSubmit();}
 const dialog=$('[role="dialog"]');
 if(event.key==='Escape'){if(dialog&&$('#modal-root').contains(dialog))closeModal();else if(current.id==='logout'||current.id==='filters')back();else clearFeedback();}
 if(event.key==='Tab'&&dialog){const nodes=$$('button:not(:disabled),a[href],input,textarea,select',dialog);const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
 if(event.target.dataset.message!==undefined&&(event.key==='Enter'||event.key===' ')){event.preventDefault();openCopy(Number(event.target.dataset.message));}
});
$('#reset-demo').addEventListener('click',()=>{if(demo.user.photo?.startsWith('blob:'))URL.revokeObjectURL(demo.user.photo);demo=initialDemo();activities.football.joined=8;delete activities.created;stack=[];keyboard=false;go('home');render();});
window.addEventListener('hashchange',render);
window.addEventListener('pagehide',()=>{clearTimeout(routeTimer);clearTimeout(feedbackTimer);clearTimeout(pressTimer);});
window.LastSpotPrototype={screens:SCREENS,go,scenario,render,get current(){return current;},get demo(){return demo;}};
render();
